#define NET_UNITS_V 0
#endif
#ifndef NS_HOLD
#define NS_HOLD 0    /* tier1m: no MSCKF feature updates until the startup net has landed (features stay queued) */
#endif
#ifndef NS_HOLD_MAX
#define NS_HOLD_MAX 1000000
#endif
#ifndef NS_DELAY
#define NS_DELAY 0   /* test: frames after K before the post-K micro-steps may run */
#endif
